// Author: MiYu. Read original Morf vertex animation and render directly from archive memory.
#include "morph_mesh.h"
#include "binary.h"
#include <DirectXMath.h>
#include <algorithm>
#include <cmath>
#include <cstring>
namespace war3 {
MorphMesh::MorphMesh(Archives& archives,Images& images,Renderer& renderer,const std::string& path,std::map<std::string,Com<IDirect3DTexture9>>& textures){
    auto member=archives.read(path);if(!member)throw std::runtime_error("Missing morph mesh: "+path);auto& bytes=member->bytes;if(bytes.size()>128u*1024u*1024u || bytes.size()<0x44)throw std::runtime_error("Invalid morph mesh size");Binary header(bytes);header.expect(tag("Morf"));auto frames=header.u32(),vertices=header.u32(),indices=header.u32();interval_=header.f32();if(!frames || frames>10000 || !vertices || vertices>65535 || !indices || indices>3000000 || indices%3 || !(interval_>0 && interval_<=60) || std::uint64_t(frames)*vertices>8000000)throw std::runtime_error("Morph mesh exceeds limits");header.take(0x44-20);if(std::uint64_t(frames+3)*4>header.left())throw std::runtime_error("Truncated morph mesh offsets");std::vector<std::uint32_t> offsets;offsets.reserve(frames+3);for(unsigned i=0;i<frames+3;++i){auto offset=header.u32();if(offset>=bytes.size() || (i && offset<=offsets.back()))throw std::runtime_error("Invalid morph mesh offset");offsets.push_back(offset);}if(offsets.front()<0x44u+std::uint64_t(frames+3)*4)throw std::runtime_error("Overlapping morph mesh offsets");auto slice=[&](unsigned index,size_t length){auto begin=offsets[index],end=index+1<offsets.size()?offsets[index+1]:bytes.size();if(length>end-begin)throw std::runtime_error("Truncated morph mesh section");return std::span<const std::uint8_t>(bytes).subspan(begin,length);};auto nameBytes=slice(0,offsets[1]-offsets[0]);Binary nameReader(nameBytes);auto textureName=nameReader.cstring(1024);if(textureName.empty())throw std::runtime_error("Missing morph texture name");if(auto found=textures.find(textureName);found!=textures.end())texture_=found->second;else{auto texture=archives.readTexture(textureName);if(!texture)throw std::runtime_error("Missing morph texture: "+textureName);auto image=images.decode(texture->bytes);texture_=renderer.texture(image.width,image.height,image.pixels);textures.emplace(textureName,texture_);}
    Binary indexReader(slice(1,size_t(indices)*2));indices_.reserve(indices);for(unsigned i=0;i<indices;++i){auto index=indexReader.u16();if(index>=vertices)throw std::runtime_error("Invalid morph mesh index");indices_.push_back(index);}Binary uvReader(slice(2,size_t(vertices)*8));uv_.reserve(vertices);for(unsigned i=0;i<vertices;++i)uv_.push_back({uvReader.f32(),uvReader.f32()});frames_.reserve(size_t(frames)*vertices);for(unsigned frame=0;frame<frames;++frame){Binary data(slice(frame+3,size_t(vertices)*24));for(unsigned i=0;i<vertices;++i)frames_.push_back({data.f32(),data.f32(),data.f32(),data.f32(),data.f32(),data.f32()});}frameCount_=frames;vertices_.resize(vertices);
}
void MorphMesh::draw(Renderer& renderer,double seconds){
    if(!std::isfinite(seconds) || seconds<0)throw std::runtime_error("Invalid morph mesh time");double frame=std::clamp(seconds/double(interval_),0.,double(frameCount_-1));auto first=size_t(frame),second=std::min(first+1,frameCount_-1);float alpha=float(frame-first);for(size_t i=0;i<vertices_.size();++i){auto& a=frames_[first*vertices_.size()+i];auto& b=frames_[second*vertices_.size()+i];vertices_[i]={std::lerp(a.x,b.x,alpha),std::lerp(a.y,b.y,alpha),std::lerp(a.z,b.z,alpha),std::lerp(a.nx,b.nx,alpha),std::lerp(a.ny,b.ny,alpha),std::lerp(a.nz,b.nz,alpha),0xffffffff,uv_[i][0],uv_[i][1]};}
    auto device=renderer.device();DirectX::XMFLOAT4X4 identity;DirectX::XMStoreFloat4x4(&identity,DirectX::XMMatrixIdentity());D3DMATRIX world;std::memcpy(&world,&identity,sizeof(world));device->SetTransform(D3DTS_WORLD,&world);device->SetFVF(D3DFVF_XYZ|D3DFVF_NORMAL|D3DFVF_DIFFUSE|D3DFVF_TEX1);device->SetTexture(0,texture_.Get());device->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_MODULATE);device->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_TEXTURE);device->SetTextureStageState(0,D3DTSS_COLORARG2,D3DTA_DIFFUSE);device->SetTextureStageState(0,D3DTSS_ALPHAOP,D3DTOP_MODULATE);device->SetTextureStageState(0,D3DTSS_ALPHAARG1,D3DTA_TEXTURE);device->SetTextureStageState(0,D3DTSS_ALPHAARG2,D3DTA_DIFFUSE);device->SetSamplerState(0,D3DSAMP_MINFILTER,D3DTEXF_LINEAR);device->SetSamplerState(0,D3DSAMP_MAGFILTER,D3DTEXF_LINEAR);device->SetSamplerState(0,D3DSAMP_ADDRESSU,D3DTADDRESS_CLAMP);device->SetSamplerState(0,D3DSAMP_ADDRESSV,D3DTADDRESS_CLAMP);device->SetRenderState(D3DRS_ZENABLE,TRUE);device->SetRenderState(D3DRS_ZWRITEENABLE,TRUE);device->SetRenderState(D3DRS_ALPHATESTENABLE,FALSE);device->SetRenderState(D3DRS_ALPHABLENDENABLE,FALSE);device->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE);if(FAILED(device->DrawIndexedPrimitiveUP(D3DPT_TRIANGLELIST,0,UINT(vertices_.size()),UINT(indices_.size()/3),indices_.data(),D3DFMT_INDEX16,vertices_.data(),sizeof(Vertex))))throw std::runtime_error("Morph mesh draw failed");
}
}
